from ta_moler.cmd.positioner_1d_krk.generic_positioner_krk import GenericPositionerKrk
from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number
import re

__author__ = 'Marcin Usielski'
__copyright__ = 'Copyright (C) 2022-2023, Nokia'
__email__ = 'marcin.usielski@nokia.com'


class SetAngle(GenericPositionerKrk):
    """set_angle command."""

    def __init__(self, connection, angle, prompt=None, newline_chars=None, runner=None):
        """
        set_angle command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SetAngle, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                       runner=runner)
        self.angle = angle
        self.ret_required = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"set_angle {self.angle}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse output.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_angle(line=line)
                self._parse_hall_sensor(line=line)
                self._parse_target_value(line=line)
            except ParsingDone:
                pass
        super(SetAngle, self).on_new_line(line=line, is_full_line=is_full_line)

    # Moving to angle 30.0 closest to given target angle 30.0
    _re_angle = re.compile(r"Moving to angle\s+(?P<ANGLE>\-?\d+\.\d+|\-?\.\d+|\-?\d+)\s+closest to given target"
                           r" angle\s+(?P<GIVEN_ANGLE>\-?\d+\.\d+|\-?\.\d+|\-?\d+)")

    # Moving to angle 30.0
    _re_angle_simple = re.compile(r"Moving to angle\s+(?P<ANGLE>\-?\d+\.\d+|\-?\.\d+|\-?\d+)")

    def _parse_angle(self, line):
        if self._regex_helper.search_compiled(SetAngle._re_angle, line):
            self.current_ret['angle_raw'] = self._regex_helper.group("ANGLE")
            self.current_ret['angle'] = convert_to_number(self._regex_helper.group("ANGLE"))
            self.current_ret['given_angle_raw'] = self._regex_helper.group("GIVEN_ANGLE")
            self.current_ret['given_angle'] = convert_to_number(self._regex_helper.group("GIVEN_ANGLE"))
            raise ParsingDone()
        elif self._regex_helper.search_compiled(SetAngle._re_angle_simple, line):
            self.current_ret['angle_raw'] = self._regex_helper.group("ANGLE")
            self.current_ret['angle'] = convert_to_number(self._regex_helper.group("ANGLE"))
            self.current_ret['given_angle_raw'] = self._regex_helper.group("ANGLE")
            self.current_ret['given_angle'] = convert_to_number(self._regex_helper.group("ANGLE"))
            raise ParsingDone()

    # Target hall sensor value is equal to: 1298
    _re_hall = re.compile(r"Target hall sensor value is equal to:\s+(?P<VALUE>\-?\d+)")

    def _parse_hall_sensor(self, line):
        if self._regex_helper.search_compiled(SetAngle._re_hall, line):
            self.current_ret['hall_sensor_raw'] = self._regex_helper.group("VALUE")
            self.current_ret['hall_sensor'] = convert_to_number(self._regex_helper.group("VALUE"))
            raise ParsingDone()

    #  Target value is equal to: 3866
    _re_target_value = re.compile(r"Target value is equal to:\s+(?P<VALUE>\-?\d+)")

    def _parse_target_value(self, line):
        if self._regex_helper.search_compiled(SetAngle._re_target_value, line):
            self.current_ret['target_value_raw'] = self._regex_helper.group("VALUE")
            self.current_ret['target_value'] = convert_to_number(self._regex_helper.group("VALUE"))
            raise ParsingDone()


